    }
    // ✅ VALIDACIÓN CRÍTICA: Verificar que todo el rango esté disponible
    const rangeValidation = this.validateDateRange(this.selectedDates.checkIn, this.selectedDates.checkOut);
    if (!rangeValidation.isValid) {
